def sequential_search(arr: list, element) -> tuple:
    """
    Performs a sequential search on an array to find an element.

    Args:
        arr: The list to search through.
        element: The element to search for.

    Returns:
        A tuple (found, index) where found is True if the element exists,
        and index is its position (or -1 if not found).
    """
    for index in range(len(arr)):
        if arr[index] == element:
            return (True, index)
    return (False, -1)
```

